#include <catch2/catch_test_macros.hpp>

#include <string>

#include "lru_cache.h"

TEST_CASE("get refreshes an entry") {
    LruCache<std::string, int> cache(2);
    cache.put("a", 1);
    cache.put("b", 2);
    REQUIRE(cache.get("a") == 1);
    cache.put("c", 3);
    CHECK(cache.contains("a"));
    CHECK_FALSE(cache.contains("b"));
}

TEST_CASE("put evicts the oldest entry") {
    LruCache<std::string, int> cache(2);
    cache.put("a", 1);
    cache.put("b", 2);
    cache.put("c", 3);
    CHECK_FALSE(cache.contains("a"));
    CHECK(cache.size() == 2);
}

TEST_CASE("put after an eviction evicts the next oldest") {
    LruCache<std::string, int> cache(2);
    cache.put("a", 1);
    cache.put("b", 2);
    cache.put("c", 3);
    cache.put("d", 4);
    CHECK_FALSE(cache.contains("b"));
    CHECK(cache.contains("c"));
}

